import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Tech Talk- For Whom the Doorbell Tolls, GPU-Initiated Key-Value Storage on Ceph","description":"","frontmatter":{"title":"Ceph Tech Talk- For Whom the Doorbell Tolls, GPU-Initiated Key-Value Storage on Ceph","date":"2026-07-10T00:00:00.000Z","updated":"2026-07-10T00:00:00.000Z","tags":["Ceph","RADOS","对象存储","性能优化","存储集群"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_Tech_Talk_-_For_Whom_the_Doorbell_Tolls_GPU-Initiated_Key-Value_Storage_on_Ceph.md","filePath":"posts/2026/Ceph_Tech_Talk_-_For_Whom_the_Doorbell_Tolls_GPU-Initiated_Key-Value_Storage_on_Ceph.md","lastUpdated":null}'),l={name:"posts/2026/Ceph_Tech_Talk_-_For_Whom_the_Doorbell_Tolls_GPU-Initiated_Key-Value_Storage_on_Ceph.md"};function i(n,e,s,d,h,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本次 Ceph Tech Talk 由 Kyle 主讲，介绍了一个名为 <strong>Rados NKV</strong>（RADOS NVMe Key-Value）的全新项目。该项目旨在将 RADOS 的强大能力通过标准化的 NVMe Key-Value 命令集暴露出来，并支持 GPU 主动发起 IO 操作（GPU-Initiated IO），实现零拷贝、高效的 AI 推理存储访问路径。</p><h2 id="背景与动机" tabindex="-1">背景与动机 <a class="header-anchor" href="#背景与动机" aria-label="Permalink to &quot;背景与动机&quot;">​</a></h2><p>早在 1997 年，OSD（Object-Based Storage Device）论文就指出存储设备本身需要具备网络可寻址性和智能化。Ceph/RADOS 深受这一思想影响。如今，AI 推理工作负载对存储系统提出了更高要求，促使社区探索将 RADOS 的能力通过更高效的接口暴露出来。</p><h2 id="rados-nkv-核心设计" tabindex="-1">Rados NKV 核心设计 <a class="header-anchor" href="#rados-nkv-核心设计" aria-label="Permalink to &quot;Rados NKV 核心设计&quot;">​</a></h2><h3 id="nvme-key-value-命令集映射" tabindex="-1">NVMe Key-Value 命令集映射 <a class="header-anchor" href="#nvme-key-value-命令集映射" aria-label="Permalink to &quot;NVMe Key-Value 命令集映射&quot;">​</a></h3><p>NVMe Key-Value 规范定义了五种基本操作：<strong>Store、Retrieve、Delete、Exist、List</strong>。Rados NKV 完整实现了这五种操作，并通过 vendor-specific 命令码额外支持 <strong>Execute</strong> 命令，用于在特定 key 上执行计算（类似 Ceph 长期支持的 CLS 机制）。</p><p>映射关系如下：</p><ul><li>NVMe namespace → RADOS namespace（实现上是对象名 key prefix，开销较低）</li><li>NVMe key → RADOS OID（对象 ID）</li><li>NVMe value → RADOS 对象数据</li></ul><p>Inline key 最多支持 16 字节，同时支持将长 key 存储在 data payload 区段的 Extended Key 模式，适合存储 SHA 等较长键名。Value 默认上限 64 MB，最大可调至 RADOS 对象上限（通常 128 MB）。</p><h3 id="逻辑架构-两段式组件拆分" tabindex="-1">逻辑架构：两段式组件拆分 <a class="header-anchor" href="#逻辑架构-两段式组件拆分" aria-label="Permalink to &quot;逻辑架构：两段式组件拆分&quot;">​</a></h3><p>Rados NKV 分为两个主要组件：</p><p><strong>1. Rados ENKV（GPU 宿主侧）</strong></p><ul><li>使用 VFIO-user 将 NVMe namespace 以 PCIe 设备形式呈现给客户端系统</li><li>经由 NVMf controller 处理命令分发，传递至 BDEV 层</li><li>采用 BDEV KV command pass-through 方案（替代早期的 KVdev 后端抽象），以 out-of-tree BDEV 模块形式构建，减少需要合并进 SPDK 的代码量</li><li>BDEV 后端实现称为 <strong>KV Rados</strong>，处理 key-value 命令</li><li>使用 <strong>Mercury</strong> RPC 框架作为传输层，支持 libfabric（TCP、InfiniBand、RoCE v2、AWS EFA 等）</li></ul><p><strong>2. NKVX（OSD 宿主侧服务）</strong></p><ul><li>提供可插拔执行运行时（基于 WebAssembly/WASM）</li><li>提供本地线性内存缓存（LRU 策略，miss 时从 RADOS cold fill，store 时 invalidate）</li><li>通过 RDMA fabric 与 Rados ENKV 通信</li></ul><p><strong>拆分原因</strong>：GPU 宿主侧需要极低的 CPU 占用（GPU 的 CPU 资源需全力用于 tokenization/detokenization/sampling），而 librados 本身 CPU 开销较高，且返回 buffer list 不利于 peer-to-peer DMA。</p><h3 id="gpu-主动发起-io-gpu-initiated-io" tabindex="-1">GPU 主动发起 IO（GPU-Initiated IO） <a class="header-anchor" href="#gpu-主动发起-io-gpu-initiated-io" aria-label="Permalink to &quot;GPU 主动发起 IO（GPU-Initiated IO）&quot;">​</a></h3><p>与传统 <strong>GPU Direct IO</strong>（CPU 仍作为 initiator，数据直接写入 VRAM）不同，<strong>GPU-Initiated IO</strong> 由 GPU 设备 kernel 直接构建 NVMe SQ（Submission Queue）和 SQE 列表，然后通过 <strong>ring the doorbell</strong> 触发 IO。</p><p>Doorbell 机制：</p><ul><li>物理 PCIe 设备上 doorbell 映射到 BAR 寄存器</li><li>本方案使用 <strong>shadow doorbell</strong>（基于共享内存或 MFD 虚拟 doorbell），Rados ENKV 在宿主侧轮询该 doorbell</li><li>数据路径通过 RDMA peer-to-peer DMA 直接在 VRAM DMA buffer 和网卡内存区域之间传输，完全绕过 DRAM，实现真正的零拷贝</li></ul><p>GPU 可通过构建一个 <strong>wavefront/warp</strong>（AMD/Nvidia 术语），在单次 doorbell 中提交最多 1024 个并发 IO 操作，实现海量并行 IO。</p><h3 id="计算存储-computational-storage" tabindex="-1">计算存储（Computational Storage） <a class="header-anchor" href="#计算存储-computational-storage" aria-label="Permalink to &quot;计算存储（Computational Storage）&quot;">​</a></h3><p>Execute 命令支持将 WASM 代码编译后作为 key 加载，并在 per-namespace 白名单授权后，对另一个 key 对象执行存储端计算。计算运行在 OSD 宿主侧（NKVX），便于数据本地化处理，类似 Ceph 原有的 CLS 机制。</p><h2 id="主要使用场景" tabindex="-1">主要使用场景 <a class="header-anchor" href="#主要使用场景" aria-label="Permalink to &quot;主要使用场景&quot;">​</a></h2><h3 id="_1-kv-cache-存储-llm-推理加速" tabindex="-1">1. KV Cache 存储（LLM 推理加速） <a class="header-anchor" href="#_1-kv-cache-存储-llm-推理加速" aria-label="Permalink to &quot;1. KV Cache 存储（LLM 推理加速）&quot;">​</a></h3><p>大语言模型推理中，<strong>KV cache</strong> 存储 prompt prefix 的注意力状态。由于多轮对话和 agentic 工作负载中 prefix 复用率极高（某编码 Agent 研究显示平均 context length 达 92K+ token），将 KV cache 持久化到存储可以：</p><ul><li>减少 Time to First Token（TTFT）</li><li>释放 GPU 显存用于 decode</li><li>降低重复 prefill 的计算开销（quadratic 复杂度）</li></ul><p>集成路径：<strong>vLLM → LMCache KV Cache（协调层）→ Nixl 插件 → Rados NKV</strong></p><h3 id="_2-模型权重流式加载-model-weight-streaming" tabindex="-1">2. 模型权重流式加载（Model Weight Streaming） <a class="header-anchor" href="#_2-模型权重流式加载-model-weight-streaming" aria-label="Permalink to &quot;2. 模型权重流式加载（Model Weight Streaming）&quot;">​</a></h3><p>使用 <strong>fast-safetensors</strong> 插件，将模型权重张量以 NVMe KV 键值对形式存储，VLM 启动时通过 peer-to-peer DMA 直接加载权重到 VRAM，无需中间 DRAM 缓冲。</p><h2 id="目标部署形态" tabindex="-1">目标部署形态 <a class="header-anchor" href="#目标部署形态" aria-label="Permalink to &quot;目标部署形态&quot;">​</a></h2><p>面向 <strong>Oberon/Helios 级别 GPU 机架</strong>（如 NVL72：72 GPU + 36 CPU/机架）：</p><ul><li>Rados ENKV 运行在 GPU 宿主的 DPU（北向 800G/400G 网络适配器）上，或作为宿主进程/Kubernetes DaemonSet 运行</li><li>Ceph 存储集群（约 36 个存储节点）作为 KV 状态/Context Memory 集群，通过 400G RDMA 与 GPU 机架互联</li><li>每块 GPU 对应约 <strong>16 TB 可用容量</strong>，重点是带宽而非容量</li><li>需要 Gen 5 NVMe + 400/800G RDMA 网络以满足 GPU 机器的存储带宽需求</li></ul><p>NKVX 到 OSD 仍使用标准 librados 和 TCP/IP 东西向通信。</p><h2 id="路线图与后续工作" tabindex="-1">路线图与后续工作 <a class="header-anchor" href="#路线图与后续工作" aria-label="Permalink to &quot;路线图与后续工作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>事项</th><th>状态/计划</th></tr></thead><tbody><tr><td>迁移代码到 Ceph GitHub 组织</td><td>本周已在 CSC 社区讨论，计划推进</td></tr><tr><td>RPM/容器构建</td><td>已有 Fedora 44 和 UBI；待补充 Rocky/Ubuntu</td></tr><tr><td>端到端验证</td><td>已在 Strix Halo（集成 GPU + 统一内存）和 g6.xlarge（独立 Nvidia GPU）完成验证</td></tr><tr><td>SPDK 上游 PR</td><td>两个 PR 支持 BDEV KV pass-through 和 peer-to-peer DMA buff；合并后可使用 stock SPDK</td></tr><tr><td>Nixl 通用 SPDK 插件</td><td>基于 VFIO-user 的通用 block/KV IO 插件，使用 positional linear hashing（128-bit key，64-bit prefix 链 + 64-bit 序列 hash）</td></tr><tr><td>fast-safetensors SPDK 插件</td><td>替代 Python 权重加载代码，通用化实现</td></tr><tr><td>CSI 驱动</td><td>基于 SPDK CSI，支持 GPU 宿主和 DPU 双模式，Kubernetes PVC 绑定 NVMe KV namespace</td></tr><tr><td>测试硬件需求</td><td>需要 Bluefield 3/4、Selene/Polar（AMD）、Intel IPU 等 DPU 设备；欢迎社区捐献或提供 VPN 访问</td></tr></tbody></table><h2 id="q-a-要点" tabindex="-1">Q&amp;A 要点 <a class="header-anchor" href="#q-a-要点" aria-label="Permalink to &quot;Q&amp;A 要点&quot;">​</a></h2><p><strong>Q: 与 Crimson/SeaStore 的关系？</strong> A: Crimson/SeaStore 作为 OSD 侧优化，可加速 NKVX 到 RADOS 的操作，属于&quot;涨潮带起所有船&quot;的改进，对 NKV 同样受益。</p><p><strong>Q: 延迟指标？</strong> A: 开发环境测试为微秒级（μs）。cache hit 走 RDMA round-trip，通常为数微秒甚至纳秒级；cold fill 延迟取决于 RADOS 本身。需要在真实规模硬件上采集实测数据。</p><p><strong>Q: 数据持久性是否使用 Ceph 复制/EC？</strong> A: 是的，数据最终持久化为 RADOS 对象，可选 replication 或 erasure coding。若使用 CRUSH-based hash 路由到 NKVX，可实现计算本地化（在持有 primary 副本的 OSD 宿主上执行计算）；EC 池场景可能改用 Maglev 或 modulo-based hashing。</p><p><strong>Q: 是否支持直接 RDMA 到 Ceph OSD 的 NVMe 设备？</strong> A: 技术挑战多（需要 libfabric messenger、解决 buffer list 抽象问题、OSD 宿主侧需要足够大 BAR 的 DPU），当前 fat cache 方案是务实的中间路径，可在 RADOS 各层逐步优化的同时受益。</p><p><strong>Q: 测试硬件从哪里获取？</strong> A: IBM 侧已有部分 GPU；计划通过 Ceph Foundation 申请资金购置 DPU，或向 DPU/加速器厂商寻求硬件捐赠。欢迎社区通过 Slack（@KVader）联系合作。</p>',43)])])}const g=t(l,[["render",i]]);export{c as __pageData,g as default};
